const body = $input.first().json.body || $input.first().json;

const project_id = String(body.project_id || '').trim();
const chapter_number = Number(body.chapter_number);
const mode = String(body.mode || 'draft').trim();
const scene_targets = Array.isArray(body.scene_targets) ? body.scene_targets : [];
const focus_notes = String(body.focus_notes || '').trim();

if (!project_id) throw new Error('project_id is required');
if (!Number.isFinite(chapter_number) || chapter_number < 1) throw new Error('chapter_number must be a positive number');
if (!['outline', 'draft'].includes(mode)) throw new Error('mode must be outline or draft');

if (!body.story_foundation_pack || typeof body.story_foundation_pack !== 'object') {
  throw new Error(
    'Validation failed: story_foundation_pack is missing or not an object. ' +
    'Send the pack JSON from Step 2 as story_foundation_pack.'
  );
}

const approved_outline = body.approved_outline || null;
const scene_cards = Array.isArray(body.scene_cards) ? body.scene_cards : [];

return [{ json: { project_id, chapter_number, mode, scene_targets, focus_notes, story_foundation_pack: body.story_foundation_pack, approved_outline, scene_cards } }];

const req = $('Validate Intake').first().json;

return [{
  json: {
    ...req,
    story_foundation_pack: req.story_foundation_pack,
    approved_outline: req.approved_outline,
    scene_cards: req.scene_cards
  }
}];

const data = $('Load Authority Context').first().json;
const pack = data.story_foundation_pack || {};
const cs = pack.completeness_status || {};

const readyForOutline = !!cs.ready_for_outline;
const readyForDrafting = !!cs.ready_for_drafting;
const mode = data.mode;

const gate_pass = (mode === 'outline') ? readyForOutline : readyForDrafting;

return [{
  json: {
    ...data,
    gate_pass,
    readiness_snapshot: {
      mode,
      ready_for_outline: readyForOutline,
      ready_for_drafting: readyForDrafting,
      blocking_issues: cs.blocking_issues || []
    }
  }
}];

const d = $('Compute Readiness').first().json;
return [{
  json: {
    success: false,
    halted: true,
    reason: 'Readiness gate failed',
    mode: d.mode,
    readiness_snapshot: d.readiness_snapshot
  }
}];

const d = $('Compute Readiness').first().json;
const pack = d.story_foundation_pack;

const compressed_context_pack = {
  project_core: pack.project_core || {},
  world_foundation: pack.world_foundation || {},
  story_engine: pack.story_engine || {},
  character_system: pack.character_system || {},
  plot_frame: pack.plot_frame || {},
  ending_design: pack.ending_design || {},
  author_preferences: pack.author_preferences || {},
  approved_outline: d.approved_outline,
  chapter_target: {
    chapter_number: d.chapter_number,
    scene_targets: d.scene_targets,
    focus_notes: d.focus_notes
  }
};

return [{ json: { ...d, compressed_context_pack } }];

const d = $('Build Context Pack').first().json;
const system = [
  'You create chapter blueprints only.',
  'Return JSON only.',
  'Do not draft prose in this step.'
].join('\n');

const user = [
  `Project: ${d.project_id}`,
  `Chapter: ${d.chapter_number}`,
  '',
  'Compressed context pack:',
  JSON.stringify(d.compressed_context_pack, null, 2),
  '',
  'Return blueprint JSON with keys:',
  '- chapter_objective',
  '- scene_sequence (array)',
  '- continuity_requirements (array)',
  '- pov_tense_voice'
].join('\n');

return [{
  json: {
    ...d,
    request_body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 4096,
      system,
      messages: [{ role: 'user', content: user }]
    }
  }
}];

const response = $('AI: Generate Blueprint').first().json;
const prev = $('Build Blueprint Request').first().json;
const raw = response.content && response.content[0] ? response.content[0].text : '';
const cleaned = raw.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();

let blueprint;
try {
  blueprint = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { parse_error: true, error_message: 'Blueprint JSON parse failed: ' + e.message, raw_response: raw } }];
}

return [{ json: { parse_error: false, ...prev, chapter_blueprint: blueprint } }];

const d = $('Parse Blueprint').first().json;

// TODO: Replace with real human decision input source.
// Expected fields from reviewer:
// approval_status: approved | rejected
// approval_notes: string
const approval_status = 'approved';
const approval_notes = 'placeholder';

return [{ json: { ...d, approval_status, approval_notes } }];

const d = $('Capture Blueprint Decision').first().json;
const system = 'Draft chapter prose from approved blueprint only. Return plain text prose.';
const user = [
  `Chapter: ${d.chapter_number}`,
  'Approved blueprint:',
  JSON.stringify(d.chapter_blueprint, null, 2),
  '',
  'Constraints:',
  '- Keep canon consistency',
  '- Match author preferences',
  '- Preserve required payoffs where applicable'
].join('\n');

return [{
  json: {
    ...d,
    request_body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 8192,
      system,
      messages: [{ role: 'user', content: user }]
    }
  }
}];

const d = $('Build Draft Request').first().json;
const r = $('AI: Draft Prose').first().json;
const draft_text = r.content && r.content[0] ? String(r.content[0].text || '').trim() : '';
if (!draft_text) throw new Error('Draft output is empty');
return [{ json: { ...d, draft_text } }];

const d = $('Extract Draft').first().json;
const system = [
  'You are a critique engine.',
  'Do not rewrite.',
  'Return JSON only with issue list and fix plan.'
].join('\n');
const user = [
  'Draft:',
  d.draft_text,
  '',
  'Return JSON:',
  '{ issues:[{type,severity,location,description,fix_plan}], summary }'
].join('\n');

return [{
  json: {
    ...d,
    request_body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 4096,
      system,
      messages: [{ role: 'user', content: user }]
    }
  }
}];

const d = $('Build Critique Request').first().json;
const r = $('AI: Critique Only').first().json;
const raw = r.content && r.content[0] ? r.content[0].text : '';
const cleaned = String(raw).replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
let critique_report;
try { critique_report = JSON.parse(cleaned); }
catch (e) { throw new Error('Critique parse failed: ' + e.message); }
return [{ json: { ...d, critique_report } }];

const d = $('Parse Critique').first().json;
const system = 'Apply fixes from critique report to draft. Return revised draft text only.';
const user = [
  'Original draft:',
  d.draft_text,
  '',
  'Critique report:',
  JSON.stringify(d.critique_report, null, 2),
  '',
  'Apply fix plan and return revised draft only.'
].join('\n');

return [{
  json: {
    ...d,
    request_body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 8192,
      system,
      messages: [{ role: 'user', content: user }]
    }
  }
}];

const d = $('Build Fix Request').first().json;
const r = $('AI: Apply Fixes').first().json;
const revised_draft = r.content && r.content[0] ? String(r.content[0].text || '').trim() : '';
if (!revised_draft) throw new Error('Revised draft is empty');
return [{ json: { ...d, revised_draft } }];

const d = $('Extract Revised Draft').first().json;

// TODO: replace with real reviewer decision source
const approval_status = 'approved';
const approval_notes = 'placeholder';

return [{ json: { ...d, post_fix_approval_status: approval_status, post_fix_approval_notes: approval_notes } }];

const d = $('Capture Post-Fix Decision').first().json;
const system = 'Final smoothing pass only. Do not alter canon facts or plot outcomes.';
const user = [
  'Revised draft:',
  d.revised_draft,
  '',
  'Perform final smoothing for rhythm and readability only.'
].join('\n');

return [{
  json: {
    ...d,
    request_body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 8192,
      system,
      messages: [{ role: 'user', content: user }]
    }
  }
}];

const d = $('Build Final Smoothing Request').first().json;
const r = $('AI: Final Smoothing').first().json;
const final_draft = r.content && r.content[0] ? String(r.content[0].text || '').trim() : '';
if (!final_draft) throw new Error('Final smoothing output is empty');
return [{ json: { ...d, final_draft } }];

const d = $('Extract Final Draft').first().json;

// TODO: Replace with Google Docs/Drive export node(s).
// This skeleton returns payload only and does not persist externally.
const export_record = {
  project_id: d.project_id,
  chapter_number: d.chapter_number,
  exported_at: new Date().toISOString(),
  final_draft: d.final_draft
};

return [{
  json: {
    success: true,
    project_id: d.project_id,
    chapter_number: d.chapter_number,
    mode: d.mode,
    merge_ready_state: d.readiness_snapshot,
    blueprint_approval_notes: d.approval_notes || '',
    post_fix_approval_notes: d.post_fix_approval_notes || '',
    critique_report: d.critique_report || {},
    export_record
  }
}];
